//  TodoExampleUITests.swift
//  TodoExampleUITests
//
//  Drives the real TodoExample app via the Accessibility API. Run via the
//  TodoExample.xcodeproj scheme (generated by `xcodegen generate` from
//  project.yml) -- Xcode wires this bundle to the TodoExample app target
//  automatically (TEST_TARGET_NAME in project.yml), so XCUIApplication()
//  launches it with no extra setup:
//
//      xcodegen generate
//      xcodebuild -project TodoExample.xcodeproj -scheme TodoExample \
//          -destination 'platform=macOS' test -only-testing:TodoExampleUITests
//
//  Requires the test runner to have Accessibility permission (System
//  Settings > Privacy & Security > Accessibility) for XCUIApplication to
//  control other processes.

import XCTest

final class TodoExampleUITests: XCTestCase {
    var app: XCUIApplication!

    override func setUpWithError() throws {
        continueAfterFailure = false
        app = XCUIApplication()
        app.launch()
    }

    override func tearDownWithError() throws {
        app?.terminate()
    }

    private func addTodo(_ title: String) {
        let field = app.textFields["newTodoTextField"]
        field.click()
        field.typeText(title)
        app.buttons["addTodoButton"].click()
    }

    /// SwiftUI's `Text` exposes its content as the accessibility *value*, not the
    /// *label*, on macOS -- `staticTexts["activeCountLabel"].label` is always empty.
    private var activeCountLabelValue: String {
        app.staticTexts["activeCountLabel"].value as? String ?? ""
    }

    func testAddingTodoShowsItInList() throws {
        addTodo("Buy milk")
        XCTAssertTrue(app.staticTexts["todoLabel-Buy milk"].exists)
        XCTAssertEqual(activeCountLabelValue, "1 item left")
    }

    func testTogglingTodoDecrementsActiveCount() throws {
        addTodo("Buy milk")
        app.buttons["toggleButton-Buy milk"].click()
        XCTAssertEqual(activeCountLabelValue, "0 items left")
    }

    func testDeletingTodoRemovesItFromList() throws {
        addTodo("Buy milk")
        app.buttons["deleteButton-Buy milk"].click()
        XCTAssertFalse(app.staticTexts["todoLabel-Buy milk"].exists)
    }

    func testClearCompletedRemovesCompletedTodos() throws {
        addTodo("Buy milk")
        addTodo("Walk dog")
        app.buttons["toggleButton-Buy milk"].click()
        app.buttons["clearCompletedButton"].click()
        XCTAssertFalse(app.staticTexts["todoLabel-Buy milk"].exists)
        XCTAssertTrue(app.staticTexts["todoLabel-Walk dog"].exists)
    }

    func testFilterActiveHidesCompletedTodos() throws {
        addTodo("Buy milk")
        addTodo("Walk dog")
        app.buttons["toggleButton-Buy milk"].click()

        app.segmentedControls["filterPicker"].buttons["Active"].click()

        XCTAssertFalse(app.staticTexts["todoLabel-Buy milk"].exists)
        XCTAssertTrue(app.staticTexts["todoLabel-Walk dog"].exists)
    }
}
